/// Build a plain node (no text/gesture/bindings) for a component.
fn plain_node(component: Component, children: Vec<Node>, properties: BTreeMap<u16, u32>) -> Node {
    Node {
        id: 0,
        component,
        children,
        properties,
        string_properties: BTreeMap::new(),
