fn grid_props(config: &GridConfig) -> BTreeMap<u16, u32> {
    let mut p = BTreeMap::new();
    if let Some(c) = config.columns {
        p.insert(property_id::GRID_COLUMNS, (c as f32).to_bits());
    }
    if let Some(r) = config.rows {
