        assert_eq!(
            text.properties.get(&property_id::BACKGROUND_COLOR),
            Some(&0xFF_EEEEEE)
        );

        let stack = vstack![].modifiers(Card).build();
        assert_eq!(
            stack.properties.get(&property_id::BACKGROUND_COLOR),
