+    /// The underlying id.
+    fn into_signal_id(self) -> SignalId;
+}
+
+impl IntoSignalId for SignalId {
+    fn into_signal_id(self) -> SignalId {
+        self
+    }
+}
+impl<T> IntoSignalId for Signal<T> {
+    fn into_signal_id(self) -> SignalId {
+        self.id()
+    }
+}
+impl<T> IntoSignalId for WritableSignal<T> {
+    fn into_signal_id(self) -> SignalId {
+        self.id()
+    }
