 #[cfg(test)]
 mod sizethatfits_tests {
     use super::*;

     #[test]
     fn fit_slot_builds_component_query_and_only_the_selected_child() {
         let view = SizeThatFits::new(vec![
             Fit::new(Text::new("wide"), 640.0),
             Fit::any(Text::new("compact")),
         ]);
         let mut root = view.build();
         let mut next = 1;
         pathland_engine::assign_ids(&mut root, &mut next);

         assert_eq!(root.component, Component::SizeThatFits);
         let query = root.list_properties.get(&property_id::FIT_QUERY).unwrap();
         assert_eq!(query.as_slice(), &[0.0, 640.0]);
         assert_eq!(root.children.len(), 1, "only the selected candidate builds");
     }

     #[test]
     fn with_fit_selects_the_requested_candidate() {
         let view = SizeThatFits::new(vec![
             Fit::new(Text::new("wide"), 640.0),
             Fit::any(Text::new("compact")),
         ])
         .with_fit(1);
         let node = view.build();
         assert_eq!(node.children.len(), 1);
         assert!(
             node.children[0].component
                 == Component::Text {
                     text: "wide".into()
                 }
         );
     }
 }

state.output:
//! Typed raw-input events (host → guest).
//!
//! Events are the **raw inputs** the renderer reports: pointer down/move/up and
//! key down/up, each carrying a host-resolved `targetId`. High-level
//! interpretations (tap, drag, long-press) are built by the guest/app from
//! these raw inputs and are NOT part of the protocol.
//!
//! Encode a raw input with `Event::encode`, decode a ring opcode with
//! `Event::try_from`.

use alloc::string::String;
use alloc::string::ToString;
use crate::category;
use crate::flag;
use crate::Opcode;

/// A raw-input event (host → guest).
///
/// `Event` is **not** `Copy`: [`Event::TextChanged`] owns the new field text
/// and [`Event::Navigate`] owns an optional URL. Simple events round-trip
/// through `encode`/`try_from` as pure 16-byte opcodes; `TextChanged` and
/// `Navigate` with a URL are encoded/decoded at the batch level (their strings
/// live in the string section / event arena, referenced by a relative/absolute
/// offset).
#[derive(Debug, Clone, PartialEq)]
pub enum Event {
    /// Pointer button pressed at a viewport-relative point.
    PointerDown {
        target: u32,
        x: f32,
        y: f32,
        secondary: bool,
    },
    /// Pointer moved; optionally entered/left the node (hover).
    PointerMove {
        target: u32,
        x: f32,
        y: f32,
        hovering: bool,
        leaving: bool,
    },
    /// Pointer button released at a viewport-relative point.
    PointerUp {
        target: u32,
        x: f32,
        y: f32,
        secondary: bool,
    },
    /// Key pressed (possibly an auto-repeat).
    KeyDown {
        target: u32,
        key_code: u16,
        modifiers: u8,
        repeat: bool,
    },
    /// Key released.
    KeyUp {
        target: u32,
        key_code: u16,
        modifiers: u8,
    },
