fn build_children(children: &[Box<dyn View>]) -> Vec<Node> {
    children.iter().map(|c| c.build()).collect()
}

// --- two-way binding sinks (app-side; never serialized) --------------------

fn text_sink(signal: WritableSignal<String>) -> Rc<RefCell<dyn FnMut(&str) + 'static>> {
    Rc::new(RefCell::new(move |value: &str| {
        signal.set(String::from(value));
    }))
}

fn value_sink_f32(signal: WritableSignal<f32>) -> Rc<RefCell<dyn FnMut(f32) + 'static>> {
    Rc::new(RefCell::new(move |value: f32| {
        signal.set(value);
    }))
}

fn value_sink_bool(signal: WritableSignal<bool>) -> Rc<RefCell<dyn FnMut(f32) + 'static>> {
    Rc::new(RefCell::new(move |value: f32| {
        signal.set(value > 0.0);
    }))
}

fn value_sink_u32(signal: WritableSignal<u32>) -> Rc<RefCell<dyn FnMut(f32) + 'static>> {
    Rc::new(RefCell::new(move |value: f32| {
        signal.set(value.max(0.0) as u32);
    }))
}

fn date_sink(signal: WritableSignal<i32>) -> Rc<RefCell<dyn FnMut(i32, u32) + 'static>> {
    Rc::new(RefCell::new(move |days: i32, _millis: u32| {
        signal.set(days);
    }))
}

