+    node.gestures.push(Gesture::ValueInput(value_sink_bool(signal)));
+}
+
+/// Bind a u32-valued property (`VALUE`, an index) to a signal (two-way).
+fn bind_value_u32(node: &mut Node, prop: u16, signal: WritableSignal<u32>) {
+    let initial = signal.get().unwrap_or(0);
+    node.properties.insert(prop, (initial as f32).to_bits());
+    node.property_bindings.insert(prop, signal.id());
+    mark_binding(node);
+    node.gestures.push(Gesture::ValueInput(value_sink_u32(signal)));
+}
+
+/// Bind a date picker's value to a days-since-epoch signal (two-way).
+fn bind_date(node: &mut Node, signal: WritableSignal<i32>) {
+    node.property_bindings.insert(property_id::VALUE, signal.id());
+    mark_binding(node);
+    node.gestures.push(Gesture::DateInput(date_sink(signal)));
+}
