input.newString:
fn value_sink_bool(signal: WritableSignal<bool>) -> Rc<RefCell<dyn FnMut(f32) + 'static>> {
    Rc::new(RefCell::new(move |value: f32| {
        signal.set(value > 0.0);
    }))
}

/// Mark a node as value/text/date bound (the renderer's event gate).
fn mark_binding(node: &mut Node) {
    node.properties.insert(property_id::BINDING_ID, 1);
}

/// Bind a text control's value to a signal (two-way).
fn bind_text(node: &mut Node, signal: WritableSignal<String>) {
    node.text_binding = Some(signal.id());
    mark_binding(node);
    node.gestures.push(Gesture::TextInput(text_sink(signal)));
}

/// Bind an f32-valued property (`VALUE`) to a signal (two-way).
fn bind_value_f32(node: &mut Node, prop: u16, signal: WritableSignal<f32>) {
    let initial = signal.get().unwrap_or(0.0);
    node.properties.insert(prop, initial.to_bits());
    node.property_bindings.insert(prop, signal.id());
    mark_binding(node);
    node.gestures.push(Gesture::ValueInput(value_sink_f32(signal)));
}

/// Bind a bool-valued property (`SELECTED`) to a signal (two-way).
fn bind_value_bool(node: &mut Node, prop: u16, signal: WritableSignal<bool>) {
    let initial = signal.get().unwrap_or(false);
    node.properties.insert(prop, if initial { 1 } else { 0 });
    node.property_bindings.insert(prop, signal.id());
    mark_binding(node);
    node.gestures.push(Gesture::ValueInput(value_sink_bool(signal)));
}

input.oldString:
fn value_sink_bool(signal: WritableSignal<bool>) -> Rc<RefCell<dyn FnMut(f32) + 'static>> {
    Rc::new(RefCell::new(move |value: f32| {
        signal.set(value > 0.0);
    }))
}

fn value_sink_u32(signal: WritableSignal<u32>) -> Rc<RefCell<dyn FnMut(f32) + 'static>> {
    Rc::new(RefCell::new(move |value: f32| {
        signal.set(value.max(0.0) as u32);
    }))
}

fn date_sink(signal: WritableSignal<i32>) -> Rc<RefCell<dyn FnMut(i32, u32) + 'static>> {
    Rc::new(RefCell::new(move |days: i32, _millis: u32| {
        signal.set(days);
    }))
}

/// Mark a node as value/text/date bound (the renderer's event gate).
fn mark_binding(node: &mut Node) {
    node.properties.insert(property_id::BINDING_ID, 1);
}

/// Bind a text control's value to a signal (two-way).
fn bind_text(node: &mut Node, signal: WritableSignal<String>) {
    node.text_binding = Some(signal.id());
    mark_binding(node);
    node.gestures.push(Gesture::TextInput(text_sink(signal)));
}

/// Bind an f32-valued property (`VALUE`) to a signal (two-way).
fn bind_value_f32(node: &mut Node, prop: u16, signal: WritableSignal<f32>) {
    let initial = signal.get().unwrap_or(0.0);
    node.properties.insert(prop, initial.to_bits());
    node.property_bindings.insert(prop, signal.id());
    mark_binding(node);
    node.gestures.push(Gesture::ValueInput(value_sink_f32(signal)));
}

/// Bind a bool-valued property (`SELECTED`) to a signal (two-way).
fn bind_value_bool(node: &mut Node, prop: u16, signal: WritableSignal<bool>) {
    let initial = signal.get().unwrap_or(false);
    node.properties.insert(prop, if initial { 1 } else { 0 });
    node.property_bindings.insert(prop, signal.id());
    mark_binding(node);
    node.gestures.push(Gesture::ValueInput(value_sink_bool(signal)));
}

/// Bind a u32-valued property (`VALUE`, an index) to a signal (two-way).
fn bind_value_u32(node: &mut Node, prop: u16, signal: WritableSignal<u32>) {
    let initial = signal.get().unwrap_or(0);
    node.properties.insert(prop, (initial as f32).to_bits());
    node.property_bindings.insert(prop, signal.id());
    mark_binding(node);
    node.gestures.push(Gesture::ValueInput(value_sink_u32(signal)));
}

/// Bind a date picker's value to a days-since-epoch signal (two-way).
fn bind_date(node: &mut Node, signal: WritableSignal<i32>) {
    node.property_bindings.insert(property_id::VALUE, signal.id());
    mark_binding(node);
    node.gestures.push(Gesture::DateInput(date_sink(signal)));
}

