         impl ViewModifier for Card {
             fn apply(&self, node: &mut Node) {
                 Padding(16.0).apply(node);
                 Background(Color::argb(0xFF_EEEEEE)).apply(node);
                 ForegroundStyle(Color::argb(0xFF_000000)).apply(node);
             }
         }

