Test:
```rust
#[test]
fn button_style_scopes_content() {
    // default style: native (no content child)
    let node = Button::with(|b| { b.label("Go"); }).build();
    assert_eq!(node.component, Component::Button { label: "Go".into() });
    assert!(node.children.is_empty());

    // bordered style adds a content child inside the button.
    let node = Button::with(|b| { b.label("Go"); })
        .button_style(BorderedButtonStyle)
        .build();
    assert_eq!(node.children.len(), 1);
    // the content is a styled text
    assert_eq!(node.children[0].component, Component::Text { text: "Go".into() });
}
```
