    path: WritableSignal<String>,
    back: Rc<RefCell<Vec<String>>>,
}

impl Router {
    pub fn new(path: WritableSignal<String>) -> Self {
        Self { path, back: Rc::new(RefCell::new(Vec::new())) }
    }
    /// The current path.
    pub fn path(&self) -> String { self.path.get().unwrap_or_default() }
    /// The back-stack depth.
    pub fn depth(&self) -> u32 { self.back.borrow().len() as u32 }
    /// Select `to` (no back-stack entry).
    pub fn navigate(&self, to: impl Into<String>) { self.path.set(to.into()); }
    /// Drill down to `to`, pushing the current path.
    pub fn push(&self, to: impl Into<String>) {
        self.back.borrow_mut().push(self.path());
        self.path.set(to.into());
    }
    /// Replace the current path (no back-stack change).
    pub fn replace(&self, to: impl Into<String>) { self.path.set(to.into()); }
    /// Go back one step.
    pub fn pop(&self) {
        if let Some(prev) = self.back.borrow_mut().pop() { self.path.set(prev); }
    }
    /// The current path signal (for host URL sync).
    pub fn signal(&self) -> WritableSignal<String> { self.path.clone() }
}

