impl StateStore for InMemoryStateStore {
    fn get(&self, key: &str) -> Option<SignalValue> { self.map.borrow().get(key).cloned() }
    fn set(&self, key: &str, value: SignalValue) { self.map.borrow_mut().insert(String::from(key), value); }
}

pub struct State<T> { signal: WritableSignal<T> }
impl<T: SignalValueKind> State<T> {
    pub fn get(&self) -> Option<T> { self.signal.get() }
    pub fn set(&self, value: T) -> Vec<SignalId> { self.signal.set(value) }
    pub fn update(&self, f: impl FnOnce(T) -> T) {
        if let Some(v) = self.get() { self.signal.set(f(v)); }
    }
    pub fn signal(&self) -> WritableSignal<T> { self.signal.clone() }
}

pub struct PersistentState {
    store: Rc<dyn StateStore>,
    scope: String,
    runtime: Runtime,
}
impl PersistentState {
    pub fn new(store: Rc<dyn StateStore>, scope: impl Into<String>, runtime: Runtime) -> Self {
        Self { store, scope: scope.into(), runtime }
    }
