        let value = self.store.get(&key).unwrap_or_else(|| initial.into_signal_value());
        let id = self.runtime.create(value);
        let signal = WritableSignal::from_id(id, &self.runtime);
        // auto-save on change
        let store = self.store.clone();
        let runtime = self.runtime.clone();
        let save_key = key;
        let save_id = id;
        self.runtime.effect(move || {
            store.set(&save_key, runtime.get(save_id));
        });
        State { signal }
    }
}
