     }
     fn config_mut(&mut self) -> &mut Self::Config {
         self.view.config_mut()
     }
 }

 impl<V: Children> Children for Modified<V> {
     fn set_children(&mut self, children: Vec<Box<dyn View>>) {
         self.view.set_children(children);
     }
