             style: None,
             family: Some(family),
             size: Some(size),
             weight: None,
             design: None,
         }
     }

     /// A system font with an exact size.
     pub const fn system(size: f32) -> Self {
         Self {
             style: None,
             family: None,
             size: Some(size),
             weight: None,
             design: None,
         }
     }

     /// A system font with an exact size + weight.
     pub const fn system_weight(size: f32, weight: f32) -> Self {
         Self {
             style: None,
             family: None,
             size: Some(size),
             weight: Some(weight),
             design: None,
         }
     }

