package com.pathland.view;

import com.pathland.view.emit.PathlandNode;
import com.pathland.view.signal.Signal;
import com.pathland.view.signal.Signals;

import java.util.List;
import java.util.function.Consumer;

/**
 * An interactive button ({@code Button}). Accepts an arbitrary child view as
 * the label. The control owns the native {@code BUTTON} node and wires the action on
 * it; the active {@link ButtonStyle} (spec DSL.md §5.7) supplies the button's content
 * as the button node's child.
 *
 * <p>Content precedence (spec DSL.md §4): a child supplied via {@code .children(…)}
 * wins, then a {@code title} value, then the style's own content.
 */
public final class Button implements View, Configurable<Button.Config>, ChildrenView {

    /** {@link Button} values. */
    public static final class Config implements View.Config {

        private Runnable action;
        private Signal<String> title;

        /** Set the tap action. */
        public Config action(Runnable action) {
            this.action = action;
            return this;
        }

        /** Set a static plain text title (used when no child is supplied). */
        public Config title(String title) {
            this.title = Signals.constant(title);
            return this;
        }

        /** Bind the plain text title to a signal. */
        public Config title(Signal<String> title) {
            this.title = title;
            return this;
        }
    }

    private final Config config;
    private List<View> children = List.of();

    private Button(Config config, List<View> children) {
        this.config = config;
        this.children = children;
    }

    /** A button with a plain text title. */
    public static Button of(String title, Runnable action) {
        return new Button(new Config().title(title).action(action), List.of());
    }

    /** A button with an arbitrary child view as its label. */
    public static Button of(View label, Runnable action) {
        return new Button(new Config().action(action), List.of(label));
    }

    /** Configure the button's values. */
    public static ViewBuilder<Button, Config> with(Consumer<Config> configure) {
        Config config = new Config();
        configure.accept(config);
        return new ViewBuilder<>(new Button(config, List.of()));
    }

    /** Supply the button's label. */
    public static ViewBuilder<Button, Config> children(View... children) {
        return new ViewBuilder<>(new Button(new Config(), List.of())).children(children);
    }

    /** Apply modifiers to an action-less button. */
    public static ViewBuilder<Button, Config> modifiers(ViewModifier... modifiers) {
        return new ViewBuilder<>(new Button(new Config(), List.of())).modifiers(modifiers);
    }

    @Override
    public Config config() {
        return config;
    }

    @Override
    public void setChildren(List<View> children) {
        this.children = List.copyOf(children);
    }

    @Override
    public PathlandNode render(Environment env) {
        // The control owns the native BUTTON shell + the action; the style supplies
        // the content (the decorated label) as the shell's child. The label keeps its
        // own component(s) and layout (Composite Override Mode, PRIMITIVES.md §2).
        View label = !children.isEmpty()
                ? children.get(0)
                : (config.title != null ? Text.of(config.title) : null);

        PathlandNode node = new PathlandNode(Components.BUTTON);
        ButtonStyle style = env.buttonStyle();
        View content = style.makeBody(new ButtonStyle.Configuration(label));
        if (content != null && content != EmptyContent.INSTANCE) {
            node.children.add(content.render(env));
        }
        Object existing = node.properties.get(Properties.EVENT_LISTENERS);
        int mask = existing instanceof Integer i ? i : 0;
        node.properties.put(
                Properties.EVENT_LISTENERS,
                mask | Commands.Listeners.POINTER_DOWN | Commands.Listeners.POINTER_UP);
        node.tapActions.add(config.action);
        return node;
    }
}

package com.pathland.view;

import com.pathland.view.emit.PathlandNode;
import com.pathland.view.signal.Signal;
import com.pathland.view.signal.Signals;
import com.pathland.view.signal.WritableSignal;

import java.util.function.Consumer;

/**
 * A single-line text input ({@code TextField}). The current value is bound to
 * a {@link WritableSignal<String>}; edits flow back through the host as
 * {@code TEXT_CHANGED} events and are written into the binding. The placeholder maps
 * to the {@code PROMPT} property.
 */
public final class TextField implements View, Configurable<TextField.Config> {

    /** {@link TextField} values. */
    public static final class Config implements View.Config {

        private Signal<String> placeholder;
        private WritableSignal<String> binding;

        /** Set a static placeholder ({@code PROMPT}). */
        public Config placeholder(String placeholder) {
            this.placeholder = Signals.constant(placeholder);
            return this;
        }

        /** Bind the placeholder ({@code PROMPT}) to a signal. */
        public Config placeholder(Signal<String> placeholder) {
            this.placeholder = placeholder;
            return this;
        }

        /** Bind the current value (two-way). */
        public Config text(WritableSignal<String> binding) {
            this.binding = binding;
            return this;
        }
    }

    private final Config config;

    private TextField(Config config) {
        this.config = config;
    }

    /** A single-line text input bound to {@code binding}. */
    public static TextField of(String placeholder, WritableSignal<String> binding) {
        return new TextField(new Config().placeholder(placeholder).text(binding));
    }

    /** Configure the text field's values. */
    public static ViewBuilder<TextField, Config> with(Consumer<Config> configure) {
        Config config = new Config();
        configure.accept(config);
        return new ViewBuilder<>(new TextField(config));
    }

    /** Apply modifiers to a bare text field. */
    public static ViewBuilder<TextField, Config> modifiers(ViewModifier... modifiers) {
        return new ViewBuilder<>(new TextField(new Config())).modifiers(modifiers);
    }

    @Override
    public Config config() {
        return config;
    }

    @Override
    public PathlandNode render(Environment env) {
        PathlandNode node = new PathlandNode(Components.TEXT_FIELD);
        if (config.placeholder != null) {
            node.property(Properties.PROMPT, config.placeholder);
        }
        if (config.binding != null) {
            node.textBinding = config.binding;
            node.text = config.binding.get();
            node.textInput = config.binding::set;
        }
        return node;
    }
}

package com.pathland.view;

import com.pathland.view.emit.PathlandNode;
import com.pathland.view.signal.Signal;
import com.pathland.view.signal.Signals;
import com.pathland.view.signal.WritableSignal;

import java.util.function.Consumer;

/**
 * A boolean switch, checkbox, or toggle button ({@code Toggle}). The visual
 * variant is the {@code TOGGLE_STYLE} token; the checked state binds to a
 * {@link WritableSignal<Boolean>} (two-way).
 */
public final class Toggle implements View, Configurable<Toggle.Config> {

    /** {@link Toggle} values. */
    public static final class Config implements View.Config {

        private Signal<ToggleStyle> style;
        private WritableSignal<Boolean> binding;
        private Signal<String> label;

        /** Set a static visual variant ({@code TOGGLE_STYLE}). */
        public Config style(ToggleStyle style) {
            this.style = Signals.constant(style);
            return this;
        }

        /** Bind the visual variant ({@code TOGGLE_STYLE}) to a signal. */
        public Config style(Signal<ToggleStyle> style) {
            this.style = style;
            return this;
        }

        /** Bind the checked state (two-way). */
        public Config isOn(WritableSignal<Boolean> binding) {
            this.binding = binding;
            return this;
        }

        /** Set a static label. */
        public Config label(String label) {
            this.label = Signals.constant(label);
            return this;
        }

        /** Bind the label to a signal. */
        public Config label(Signal<String> label) {
            this.label = label;
            return this;
        }
    }

    private final Config config;

    private Toggle(Config config) {
        this.config = config;
    }

    /** A toggle with a style token, a binding, and a label. */
    public static Toggle of(ToggleStyle style, WritableSignal<Boolean> binding, String label) {
        return new Toggle(new Config().style(style).isOn(binding).label(label));
    }

    /** A {@code Switch}-style toggle with no label. */
    public static Toggle of(WritableSignal<Boolean> binding) {
        return new Toggle(new Config().isOn(binding));
    }

    /** A {@code Switch}-style toggle with a label ({@code Toggle("label", isOn:)}). */
    public static Toggle of(String label, WritableSignal<Boolean> binding) {
        return new Toggle(new Config().isOn(binding).label(label));
    }

    /** Configure the toggle's values. */
    public static ViewBuilder<Toggle, Config> with(Consumer<Config> configure) {
        Config config = new Config();
        configure.accept(config);
        return new ViewBuilder<>(new Toggle(config));
    }

    /** Apply modifiers to a bare toggle. */
    public static ViewBuilder<Toggle, Config> modifiers(ViewModifier... modifiers) {
        return new ViewBuilder<>(new Toggle(new Config())).modifiers(modifiers);
    }

    @Override
    public Config config() {
        return config;
    }

    @Override
    public PathlandNode render(Environment env) {
        PathlandNode node = new PathlandNode(Components.TOGGLE);
        node.property(Properties.TOGGLE_STYLE,
                config.style != null ? config.style : Signals.constant(ToggleStyle.SWITCH));
        if (config.binding != null) {
            node.properties.put(Properties.SELECTED, config.binding.get() ? 1 : 0);
            node.propertyBindings.put(Properties.SELECTED, config.binding);
            node.valueInput = v -> config.binding.set(v > 0f);
        }
        if (config.label != null) {
            node.property(Properties.LABEL, config.label);
