package com.pathland.view;

import com.pathland.view.signal.Signal;

import java.util.function.Consumer;

/**
 * Scopes an {@link EnvironmentKey} → value binding down a wrapped subtree
 * ({@code .modifiers(EnvironmentBinding.with(e -> e.key(...).value(...)))}): the value
 * is active only while that subtree renders, and an outer binding is restored
 * afterward — nearest wins (spec DSL.md §5.5). Read it with
 * {@code Environment.value(key)}, which **always returns a signal**: a plain value is
 * wrapped in a constant signal; a signal value is returned as-is and stays reactive.
 * The modifier value is applied with {@code .modifiers(...)} like any other.
 */
public final class EnvironmentBinding implements ViewModifier {

    /** {@link EnvironmentBinding} values. */
    public static final class Config {

        private EnvironmentKey<?> key;
        private Object value;

        /** The environment key to bind. */
        public Config key(EnvironmentKey<?> key) {
            this.key = key;
            return this;
        }

        /** Bind a plain value (read back as a constant signal). */
        public Config value(Object value) {
            this.value = value;
            return this;
        }

        /** Bind a reactive value (the signal is returned as-is by {@link Environment#value}). */
        public Config value(Signal<?> value) {
            this.value = value;
            return this;
        }
    }

    private final EnvironmentKey<?> key;
    private final Object value;

    private EnvironmentBinding(Config config) {
        this.key = config.key;
        this.value = config.value;
    }

    /** Configure the binding ({@code EnvironmentBinding.with(e -> e.key(...).value(...))}). */
    public static EnvironmentBinding with(Consumer<Config> configure) {
        Config config = new Config();
        configure.accept(config);
        return new EnvironmentBinding(config);
    }

    @SuppressWarnings("unchecked")
    @Override
    public View body(View content) {
        return new EnvironmentView(content, (EnvironmentKey<Object>) key, value);
    }
}

package com.pathland.view;

import java.util.function.Consumer;

/**
 * Registers a listener for the active platform path (spec DSL.md §4.5) — the
 * {@code onOpenURL} idea generalized across platforms. Applied as a modifier value:
 * {@code .modifiers(PathChange.with(p -> p.listener(path -> …)))}. The listener fires
 * whenever the {@link Platform#ACTIVE_PATH} signal changes (including its initial
 * value); a {@code Router}, when present, binds to the same signal.
 */
public final class PathChange implements ViewModifier {

    /** {@link PathChange} values. */
    public static final class Config {

        private Consumer<String> listener;

        /** The listener to fire on every active-path change. */
        public Config listener(Consumer<String> listener) {
            this.listener = listener;
            return this;
        }
    }

    private final Consumer<String> listener;

    private PathChange(Config config) {
        this.listener = config.listener;
    }

    /** Configure the path-change listener ({@code PathChange.with(p -> p.listener(...))}). */
    public static PathChange with(Consumer<Config> configure) {
        Config config = new Config();
        configure.accept(config);
        return new PathChange(config);
    }

    @Override
    public View body(View content) {
        return new PathChangeView(content, listener);
    }
}

package com.pathland.view.router;

import com.pathland.view.View;
import com.pathland.view.ViewModifier;

/**
 * The navigation action modifier (spec DSL.md §4.5 "any component can change the
 * route"): marks a view as a route-changer, applied with
 * {@code .modifiers(NavigationIntent.navigate/push/replace(path))}. The intent is
 * resolved to the nearest enclosing {@link Router} by the emitter, so no router is
 * threaded by hand:
 *
 * <pre>{@code
 * Button.with(b -> b.title("Go to kitchen").action(...))
 *       .modifiers(NavigationIntent.navigate("/kitchen"));   // direct selection
 * Button.with(b -> b.title("Open item").action(...))
 *       .modifiers(NavigationIntent.push("/item/1"));        // drill-down (back-stack)
 * Button.with(b -> b.title("Swap").action(...))
 *       .modifiers(NavigationIntent.replace("/settings"));   // guard redirect / replace
 * }</pre>
 */
public final class NavigationIntent implements ViewModifier {

    private final String to;
    private final NavOp op;

    private NavigationIntent(String to, NavOp op) {
        this.to = to;
        this.op = op;
    }

    /** A {@link NavOp#NAVIGATE} route-change to {@code to}. */
    public static NavigationIntent navigate(String to) {
        return new NavigationIntent(to, NavOp.NAVIGATE);
    }

    /** A {@link NavOp#PUSH} route-change to {@code to} (drill-down). */
    public static NavigationIntent push(String to) {
        return new NavigationIntent(to, NavOp.PUSH);
    }

    /** A {@link NavOp#REPLACE} route-change to {@code to}. */
    public static NavigationIntent replace(String to) {
        return new NavigationIntent(to, NavOp.REPLACE);
    }

    @Override
    public View body(View content) {
        return new NavigationIntentView(content, to, op);
    }
}

